public class Solution {
  /**
   * Misra-Gries：第一遍最多维护 k 个计数器（命中 ++；不命中且有槽就新增；
   * 否则全体 -1 并压缩掉归零者），第二遍只对候选 key 精确复核 freq * (k+1) > n。
   * 内存 O(k)，两遍扫描。
   */
  public static int[] heavyHitters(int[] stream, int k) {
    if (stream.length == 0 || k <= 0) return new int[0];
    int[] cand = new int[k];
    int[] cnt = new int[k];
    int m = 0;
    for (int v : stream) {
      int pos = -1;
      for (int t = 0; t < m; t++) {
        if (cand[t] == v) { pos = t; break; }
      }
      if (pos >= 0) { cnt[pos]++; continue; }
      if (m < k) { cand[m] = v; cnt[m] = 1; m++; continue; }
      int w = 0;
      for (int t = 0; t < m; t++) {
        if (--cnt[t] > 0) {          // 一轮抵消：k 个计数器各减 1，归零的候选被压缩掉
          cand[w] = cand[t];
          cnt[w] = cnt[t];
          w++;
        }
      }
      m = w;
    }
    java.util.TreeSet<Integer> hit = new java.util.TreeSet<>();
    for (int t = 0; t < m; t++) {
      long freq = 0;
      for (int v : stream) {
        if (v == cand[t]) freq++;
      }
      if (freq * (k + 1L) > stream.length) hit.add(cand[t]);   // 整数比较，不用浮点阈值
    }
    int[] out = new int[hit.size()];
    int idx = 0;
    for (int v : hit) out[idx++] = v;
    return out;
  }
}

runner.naiveSolution:
public class Solution {
  // 朴素：全量 HashMap 计数后取"频次前 k 名"。内存随 key 基数增长（网关预算立刻被打爆），
  // 而且完全没有阈值概念 —— 不达标的 key 也会被报告出来。
  public static int[] heavyHitters(int[] stream, int k) {
    java.util.Map<Integer, Integer> count = new java.util.HashMap<>();
    for (int v : stream) count.merge(v, 1, Integer::sum);
    java.util.List<Integer> keys = new java.util.ArrayList<>(count.keySet());
    keys.sort((x, y) -> {
      int c = Integer.compare(count.get(y), count.get(x));
      return c != 0 ? c : Integer.compare(x, y);
    });
    int want = Math.min(Math.max(k, 0), keys.size());
    int[] out = new int[want];
    for (int t = 0; t < want; t++) out[t] = keys.get(t);
    java.util.Arrays.sort(out);
    return out;
  }
}
